targets.rawSql:
SELECT COUNT(*) AS "行程数"
FROM drives
WHERE car_id = $car_id AND end_date IS NOT NULL AND $__timeFilter(start_date);

SELECT COALESCE(convert_km(SUM(distance)::numeric, '$length_unit'), 0) AS distance_$length_unit
FROM drives
WHERE car_id = $car_id AND end_date IS NOT NULL AND $__timeFilter(start_date);

SELECT COALESCE(SUM(duration_min), 0) * 60 AS "驾驶时长"
FROM drives
WHERE car_id = $car_id AND end_date IS NOT NULL AND $__timeFilter(start_date);

SELECT COUNT(*) AS "充电次数"
FROM charging_processes
WHERE car_id = $car_id AND end_date IS NOT NULL AND $__timeFilter(start_date);

SELECT ROUND(COALESCE(SUM(charge_energy_added), 0)::numeric, 1) AS "充入电量"
FROM charging_processes
WHERE car_id = $car_id AND end_date IS NOT NULL AND $__timeFilter(start_date);
